//https://leetcode.com/problems/count-good-meals/
class Solution {
public:
    int countPairs(vector<int>& deliciousness) {
        unordered_map<int, int> m;
        for(auto i: deliciousness){
            m[i]++;
        }
        vector<long long> v;
        v.resize(32);
        for(int i=0; i<=31; i++){
            v[i] = (1LL << i);
        }

        long long count = 0;
        for(auto num: deliciousness){
            for(auto t: v){
                if(m.count(t - num)){
                    if(num == (t-num) && m[num] > 1){
                        count += m[num] - 1;
                    }else if(num != (t-num)){
                        count += m[t-num];
                    }
                }
            }
        }
        count = count/2;
        int MOD = 1000000007;
        return (int)(count % MOD);
    }
};
